"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["3526"],{96484(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.escala_numerica_obrigatoria","status":422,"titulo":"Escala do tipo de conceito num\xe9rico \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.escala_numerica_obrigatoria","requisitos":[],"oQueAconteceu":["O tipo de conceito \xe9 de natureza `numerico`, mas o campo `numerico` est\xe1 ausente ou nulo, ou falta alguma de suas tr\xeas partes: `escalaMinima`, `escalaMaxima` e `casasDecimais`. Os campos da escala s\xe3o declarados como anul\xe1veis de prop\xf3sito, para que a aus\xeancia chegue \xe0 regra do dom\xednio e responda 422 com o c\xf3digo desta p\xe1gina, em vez de uma recusa gen\xe9rica de 400. A cria\xe7\xe3o (`POST /api/configuracao/admin/tipos-conceito`) e a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) conferem a mesma regra.","A recusa vem na lista `errors` da resposta, com `field` igual a `numerico`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na atualiza\xe7\xe3o, com o corpo desserializ\xe1vel e o `id` do corpo igual ao da rota, a confer\xeancia do corpo vem antes da busca do tipo: com um `{id}` que n\xe3o existe, a resposta \xe9 esta, e n\xe3o a de [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado). O corpo que n\xe3o desserializa e o `id` do corpo diferente do da rota s\xe3o recusados antes, com 400 e sem o c\xf3digo desta p\xe1gina. Como a atualiza\xe7\xe3o sempre traz os par\xe2metros da natureza escolhida, trocar um tipo categ\xf3rico por num\xe9rico exige enviar a escala completa."],"comoResolver":["Envie `numerico` com `escalaMinima`, `escalaMaxima` e `casasDecimais` (de 0 a 4) e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito","Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);